import React from 'react';
import { Image, View } from 'react-native';
import type { SceneId } from '../domain/model';

const previews = {
  embroidery: require('../../assets/previews/embroidery.png'),
  rain: require('../../assets/previews/rain.png'),
};
/** Generated by the same artwork renderer; no fonts, masks or native surfaces on gallery mount. */
export function Preview({ id, width }: { id: SceneId; width: number }) {
  const height = (width * 16) / 9;
  return (
    <View style={{ width, height, borderRadius: 16, overflow: 'hidden' }}>
      <Image
        source={previews[id]}
        style={{ width, height }}
        resizeMode="contain"
        accessible={false}
      />
    </View>
  );
}
